describe("schema scope catalog", () => {
  test("catalogues declared scopes and reports every retired placement and unresolved binding", async () => {
    const library = await import("../../🔍️discovery/🟦️.ts");
    const taxonomy = library.loadCatalogTaxonomy();
    const casesPath = join(import.meta.dir, "../../🧫️fixtures/🧬️schema-scope-catalog/🔣️.json");
    const cases = JSON.parse(readFileSync(casesPath, "utf8")) as { contract: string; cases: { id: string; files: Record<string, unknown>; expected: { scopes: Record<string, { path: string; level: string; exports: Record<string, { file: string; facet: string }>; dependsOn: string[] }>; diagnosticCodes: string[]; placementPaths: string[] }; schemaGrammar?: Record<string, boolean> }[] };
    const authority = JSON.parse(readFileSync(join(import.meta.dir, "../../🧬️schema/🧬️schema-scope-catalog/🔣️.json"), "utf8"));
    const ajv = new Ajv({ strict: true });
    const admitScope = ajv.compile(authority);

    for (const row of cases.cases) {
      const root = mkdtempSync(join(process.env.SEMIO_TEST_ARTIFACT_DIR ?? tmpdir(), "semio-schema-scope-"));
      try {
        for (const [rel, body] of Object.entries(row.files)) {
          const abs = join(root, rel);
          mkdirSync(dirname(abs), { recursive: true });
          writeFileSync(abs, typeof body === "string" ? body : `${JSON.stringify(body, null, 2)}\n`);
        }
        for (const [path, expected] of Object.entries(row.schemaGrammar ?? {})) expect(new Ajv({ strict: false }).validateSchema(row.files[path]), row.id).toBe(expected);
        const inventory = library.inventorySchemaScopes(root, taxonomy);
        const scopes = Object.fromEntries(Object.entries(inventory.catalog.scopes).map(([id, scope]) => [id, { path: scope.path, level: scope.level, exports: scope.exports, dependsOn: [...scope.dependsOn] }]));
        for (const scope of Object.values(scopes)) expect(admitScope(scope), JSON.stringify(admitScope.errors)).toBe(true);
        expect({ case: row.id, scopes }).toEqual({ case: row.id, scopes: row.expected.scopes });
        expect({ case: row.id, codes: inventory.diagnostics.map(({ code }) => code).sort() }).toEqual({ case: row.id, codes: [...row.expected.diagnosticCodes].sort() });
        expect({ case: row.id, paths: inventory.placement.map(({ path }) => path).sort() }).toEqual({ case: row.id, paths: [...row.expected.placementPaths].sort() });
        expect(library.renderSchemaCatalog(inventory.catalog)).toBe(library.renderSchemaCatalog(library.inventorySchemaScopes(root, taxonomy).catalog));
      } finally {
        rmSync(root, { recursive: true, force: true });
      }
    }
  });

  test("resolves scope ids and export bindings only from declared identity", async () => {
    const library = await import("../../🔍️discovery/🟦️.ts");
    const taxonomy = library.loadCatalogTaxonomy();
    expect(library.schemaScopeIdFromDocumentId("https://json.schemas.assets.semio-tech.com/s/trinity/jack/artifact.json", taxonomy)).toBe("s.trinity.jack");
    expect(library.schemaScopeIdFromDocumentId("https://json.schemas.assets.semio-tech.com/hub/inference/contract.json", taxonomy)).toBe("hub.inference");
    expect(library.schemaScopeIdFromDocumentId("urn:semio:hub:inference", taxonomy)).toBe(null);
    expect(library.schemaScopeIdFromDocumentId("https://json.schemas.assets.semio-tech.com/contract.json", taxonomy)).toBe(null);
    expect(library.parseSchemaExportUri("schema://hub.inference/InferenceApproval", taxonomy)).toEqual({ scopeId: "hub.inference", exportId: "InferenceApproval" });
    expect(library.parseSchemaExportUri("schema://hub.inference/inferenceApproval", taxonomy)).toBe(null);
    expect(library.parseSchemaExportUri("local://hub.inference/InferenceApproval", taxonomy)).toBe(null);
    expect(library.schemaScopeOwnerLevel("✏️s/🔌️plugins/🔱️trinity", taxonomy)).toBe("plugin-root");
    expect(library.schemaScopeOwnerLevel("🌎️hub/📦️packages/🦀️rust/🧪️fixtures/👥️presence-lease-v1", taxonomy)).toBe(null);
    expect(library.resolveSchemaFacetKind("🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/🧬️schema", taxonomy)).toBe("📜️interface");
    expect(library.resolveSchemaFacetKind("🌎️hub/💡️inference/🧬️schema", taxonomy)).toBe(taxonomy.schemaDefaultFacetKind);
  });

  test("cross-checks the Rust export registry dump against the catalog on the resolution key", async () => {
    const library = await import("../../🔍️discovery/🟦️.ts");
    const taxonomy = library.loadCatalogTaxonomy();
    const casesPath = join(import.meta.dir, "../../🧫️fixtures/🧬️schema-rust-entries/🔣️.json");
    const cases = JSON.parse(readFileSync(casesPath, "utf8")) as { contract: string; cases: { id: string; scopes: Record<string, { path: string; formats: Record<string, string>; exports: Record<string, { file: string; facet: string }> }>; dump: { contractId: string; generator: string; entries: { scope: string; export: string; format: string }[] }; complete: boolean; expectedCodes: string[] }[] };
    const authority = JSON.parse(readFileSync(join(import.meta.dir, "../../🧬️schema/🧬️schema-rust-entries/🔣️.json"), "utf8"));

    for (const row of cases.cases) {
      const catalog = { contractId: taxonomy.schemaExportResolution.catalogContractId, catalogVersion: 1 as const, generator: taxonomy.schemaExportResolution.generator, taxonomySchemaVersion: taxonomy.schemaVersion, jsonSchemaDialect: taxonomy.schemaJsonDialect, scopes: Object.fromEntries(Object.entries(row.scopes).map(([id, scope]) => [id, { ...scope, level: "artifact-standard-subset", facetKind: taxonomy.schemaDefaultFacetKind, dependsOn: [], hashes: {} }])) };
      const findings = library.schemaRustEntryDiagnostics(catalog, row.dump, taxonomy, row.complete);
      expect({ case: row.id, codes: findings.map(({ code }) => code).sort() }).toEqual({ case: row.id, codes: [...row.expectedCodes].sort() });
      expect(findings.every(({ path, detail }) => path === taxonomy.schemaExportResolution.catalogPath && detail.length > 16)).toBe(true);
    }
  });

  test("declares one draft-07 dialect that an independent validator accepts", async () => {
    const library = await import("../../🔍️discovery/🟦️.ts");
    const taxonomy = library.loadCatalogTaxonomy();
    expect(taxonomy.schemaJsonDialect).toBe(taxonomy.mutationPayloadSchemaAuthority.jsonSchemaDialect);
    const document = { $schema: taxonomy.schemaJsonDialect, $id: "https://json.schemas.assets.semio-tech.com/repo/library/probe.json", title: "Probe", type: "object", additionalProperties: false, properties: { id: { type: "string" } }, required: ["id"] };
    const validate = new Ajv({ strict: true }).compile(document);
    expect(validate({ id: "a" })).toBe(true);
    expect(validate({ id: 1 })).toBe(false);
  });
});
