  test("structured reference adapters emit locations, old/new values, and preimage hashes",()=>runCargoCliCommand(normalizationProbeOwner(),async()=>{
    const fixture = normalizationFixture("references", {
      "package.json": "{\"name\":\"fixture\",\"exports\":{\".\":\"./🧪️subject/🟦️component.ts\"}}\n",
