  for (const failureStage of ["after-staging", "after-moves", "after-edits", "before-verify"] as const) {
    test(`rolls back byte-for-byte when failure is injected at ${failureStage}`,()=>runCargoCliCommand(normalizationProbeOwner(),async()=>{
      const fixture = normalizationFixture(`failure-${failureStage}`, {
        "🟦️subject.ts": "export const value = 1;\n",
        "🧪️consumer/🟦️.ts": "export { value } from \"🧪️tests/🧪️fixture/🟦️subject.ts\";\n",
      });
      try {
        const { plan } = (await normalizationPlan(fixture));
        expect(plan.moves.length).toBeGreaterThan(0);
        const before = normalizationWorkspaceSnapshot(fixture.workspace);
        (await expectNormalizationApplyFailure(async () => (await runCargoCliCommand(normalizationProbeOwner(),async()=>applyTaxonomyPlan(plan,{...{ repoRoot: fixture.repoRoot, ticketDir: fixture.ticketDir, expectedBaselineCommit: plan.baselineCommit, expectedPlanDigest: plan.planDigest, injectFailureAt: failureStage },cargoOwner:cargoCommandOwner()})))));
        expect(normalizationWorkspaceSnapshot(fixture.workspace)).toEqual(before);
        expect(opaqueTreeDigest(fixture.repoRoot, "compose")).toEqual(fixture.opaqueDigest);
      } finally {
        rmSync(fixture.root, { recursive: true, force: true });
      }
    }));
  }

  test("cancellation rolls back and a successful retry converges to an empty second plan",()=>runCargoCliCommand(normalizationProbeOwner(),async()=>{
    const cancelled = normalizationFixture("cancel", { "🟦️.ts": "export const value = 1;\n" });
    try {
      const { plan } = (await normalizationPlan(cancelled));
      const before = normalizationWorkspaceSnapshot(cancelled.workspace);
      const cancelFile = join(cancelled.ticketDir, "cancel");
      writeFileSync(cancelFile, "cancel\n");
      (await expectNormalizationApplyFailure(async () => (await runCargoCliCommand(normalizationProbeOwner(),async()=>applyTaxonomyPlan(plan,{...{ repoRoot: cancelled.repoRoot, ticketDir: cancelled.ticketDir, expectedBaselineCommit: plan.baselineCommit, expectedPlanDigest: plan.planDigest, cancelFile },cargoOwner:cargoCommandOwner()})))));
      expect(normalizationWorkspaceSnapshot(cancelled.workspace)).toEqual(before);
      expect(opaqueTreeDigest(cancelled.repoRoot, "compose")).toEqual(cancelled.opaqueDigest);
    } finally {
      rmSync(cancelled.root, { recursive: true, force: true });
    }

    const fixture = normalizationFixture("convergence", { "🦀️.rs": "pub const VALUE: i32 = 1;\n" });
    try {
      const { plan } = (await normalizationPlan(fixture));
      expect(plan.unresolved).toEqual([]);
      const result = (await runCargoCliCommand(normalizationProbeOwner(),async()=>applyTaxonomyPlan(plan,{...{ repoRoot: fixture.repoRoot, ticketDir: fixture.ticketDir, expectedBaselineCommit: plan.baselineCommit, expectedPlanDigest: plan.planDigest },cargoOwner:cargoCommandOwner()})));
      expect(result.planDigest).toBe(plan.planDigest);
      expect(result.appliedMoves).toBe(plan.moves.length);
      expect(result.appliedEdits).toBe(plan.edits.length);
      expect(String(result.state)).toMatch(/^(?:applied|committed|complete)$/u);
      const verification = (await runCargoCliCommand(normalizationProbeOwner(),async()=>verifyTaxonomy(await admitTaxonomyInventoryOptions({ ...fixture.options, baselineCommit: fixture.baselineCommit, excludedTreeDigests: [fixture.opaqueDigest] },cargoCommandOwner().operation))));
      expect(canonicalJson(verification)).not.toMatch(/"severity":"error"/u);
      const secondInventory = (await runCargoCliCommand(normalizationProbeOwner(),async()=>inventoryTaxonomy(await admitTaxonomyInventoryOptions(fixture.options,cargoCommandOwner().operation))));
      const secondPlan = (await runCargoCliCommand(normalizationProbeOwner(),async()=>planTaxonomy(secondInventory,{...{ baselineCommit: fixture.baselineCommit, excludedTreeDigests: [fixture.opaqueDigest] },cargoOperation:cargoCommandOwner().operation})));
      expect(secondPlan.moves).toEqual([]);
      expect(secondPlan.edits).toEqual([]);
      expect(secondPlan.regenerations).toEqual([]);
      expect(secondPlan.unresolved).toEqual([]);
      expect(opaqueTreeDigest(fixture.repoRoot, "compose")).toEqual(fixture.opaqueDigest);
    } finally {
      rmSync(fixture.root, { recursive: true, force: true });
    }
  }),120_000);
});
